import React, { createContext, useContext, useState } from 'react';

const AuthContext = createContext(null);

export const MOCK_USER = {
  name: 'Arjun Sharma',
  email: 'arjun@example.com',
  avatar: 'AS',
  enrolled: ['Mathematics', 'Physics', 'Computer Science', 'Chemistry'],
};

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  const login = (email, password) => {
    if (email && password.length >= 4) {
      const emailPrefix = email.split('@')[0];
      const avatar = emailPrefix.slice(0, 2).toUpperCase();
      setUser({ ...MOCK_USER, name: email, email, avatar, testScores: [] });
      return true;
    }
    return false;
  };

  const logout = () => setUser(null);

  const saveScore = (testData, pct, timeSpent) => {
    if (!user) return;
    const newScore = {
      id: `s${Date.now()}`,
      subject: testData.subject,
      test: testData.title,
      score: pct,
      total: 100,
      date: new Date().toISOString().split('T')[0],
      time: timeSpent,
      rank: Math.floor(Math.random() * 500) + 1,
    };
    setUser({ ...user, testScores: [...(user.testScores || []), newScore] });
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, saveScore }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
